import{S as a}from"./shared-Crjz4w_p.js";const e={"acu-n1-l01":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La música es el arte de organizar sonidos y silencios en el tiempo. Cuando tocas, eliges qué sonidos suenan, cuánto duran y en qué momento aparecen.","Casi toda la música que escuchas tiene tres ingredientes: la melodía (las notas que puedes cantar), la armonía (varias notas sonando juntas, como un acorde) y el ritmo (la forma en que los sonidos se acomodan en el tiempo)."],tips:["Escucha una canción que te guste y trata de distinguir: ¿qué parte cantarías?, ¿qué instrumentos acompañan?, ¿dónde sientes el ritmo?"]},practica:{paragraphs:["Partes: cabeza con clavijas, mástil con trastes, cuerpo (caja de resonancia) con la boca, el puente y la cejuela. La caja amplifica el sonido de las cuerdas de acero, por eso la acústica suena fuerte sin amplificador.","Sentado, apoya la cintura de la guitarra sobre la pierna derecha (si eres diestro), con la espalda recta y el mástil un poco hacia arriba. El brazo derecho descansa sobre el borde del cuerpo, cerca del puente."],tips:["Si la caja es grande (tipo dreadnought), inclínala apenas hacia ti para ver el diapasón sin encorvarte."]},lectura:{paragraphs:["El pentagrama es el lugar donde se escriben las notas. Tiene 5 líneas y 4 espacios entre ellas.","Las líneas y los espacios se cuentan de abajo hacia arriba: la línea 1 es la de hasta abajo y la 5 la de hasta arriba. Mientras más arriba esté una nota, más aguda suena.","Cuando una nota no cabe, se usan líneas adicionales: rayitas cortas por encima o por debajo del pentagrama."],tips:['Practica señalando: "línea 2", "espacio 3"… hasta que lo digas sin contar.']},oido:{paragraphs:["La altura de un sonido nos dice si es agudo (como un silbido) o grave (como un tambor grande). Depende de qué tan rápido vibra la cuerda.","En la guitarra, las cuerdas gruesas suenan más graves y las delgadas más agudas. En una misma cuerda, mientras más cerca del cuerpo de la guitarra presionas, más aguda es la nota."],tips:["Toca la cuerda 6 al aire y luego la 1: escucha la diferencia.",'Haz el ejercicio interactivo "¿Agudo o grave?" de esta lección.']}}},"acu-n1-l02":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['Todo sonido tiene cuatro propiedades: altura (agudo o grave), duración (largo o corto), intensidad (fuerte o suave) y timbre (el "color" que nos permite saber si suena una guitarra, una voz o un piano).',"Cuando tocas guitarra controlas las cuatro: qué nota tocas, cuánto la dejas sonar, con cuánta fuerza la atacas y cómo suena tu instrumento y amplificador."],tips:["Toca una misma nota cuatro veces cambiando solo una propiedad cada vez."]},practica:{paragraphs:["El metrónomo marca un pulso constante. Se mide en BPM (pulsos por minuto): 60 BPM es un pulso por segundo.","Practicar con metrónomo te ayuda a tocar parejo, sin acelerar ni frenar, y a poder tocar con otros músicos o sobre pista.","Empieza lento, a una velocidad en la que todo te salga limpio. Cuando lo toques bien tres veces seguidas, sube unos 5 BPM."],tips:["Usa el metrónomo de la app (sección Recursos).","Tocar lento y limpio es mejor que rápido y sucio."]},lectura:{paragraphs:["El pulso es el latido constante de la música: lo que marcas con el pie al escuchar una canción.","Los pulsos se agrupan en compases, separados por barras verticales. En el compás de 4/4 cada compás tiene 4 tiempos y la negra dura un tiempo.","El primer tiempo de cada compás suele sentirse más fuerte: UNO, dos, tres, cuatro."],tips:['Cuenta en voz alta "1, 2, 3, 4" mientras escuchas una canción y aplaude en el 1.']},oido:{paragraphs:["Seguir el pulso es la base de tocar con otros. Escucha el clic y trata de aplaudir exactamente al mismo tiempo, ni antes ni después.","Si te adelantas o te atrasas, no te detengas: escucha y ajusta poco a poco."],tips:['Haz el ejercicio "Sigue el pulso": toca el botón al mismo tiempo que el clic.']}}},"acu-n1-l03":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La tablatura (TAB) es una forma sencilla de escribir música para guitarra. Tiene 6 líneas, una por cada cuerda.","La línea de arriba es la 1ª cuerda (Mi aguda, la más delgada) y la de abajo es la 6ª cuerda (Mi grave, la más gruesa). ¡Ojo! Es al revés de como ves las cuerdas al mirar hacia abajo.","Los números indican el traste que debes presionar. El 0 significa cuerda al aire (sin presionar)."]},practica:{paragraphs:["Toca melodías sencillas en las cuerdas 1 y 2 leyendo tablatura. Cada número es el traste; 0 es cuerda al aire. Empieza lento y con el metrónomo."],tips:["Con cuerdas de acero, presiona justo detrás del traste: duele menos y suena más limpio."],tab:`e|-0-1-3-1-0-------|
B|-----------3-1-0-|
G|-----------------|
D|-----------------|
A|-----------------|
E|-----------------|`},lectura:{paragraphs:["La tablatura se lee de izquierda a derecha, como un texto.","Si hay números uno encima de otro, esas notas se tocan al mismo tiempo (como en un acorde). Si están uno después de otro, se tocan en orden.","La TAB básica no siempre indica el ritmo; por eso es útil escuchar la canción o combinarla con partitura."],tips:['Haz el ejercicio "Lee la tablatura" de esta lección.']},oido:{paragraphs:["En la guitarra puedes tocar la misma nota en diferentes cuerdas. Por ejemplo, el traste 5 de la 6ª cuerda suena igual que la 5ª cuerda al aire (La).","Aunque sea la misma nota, puede sonar un poco distinta (timbre), porque cada cuerda tiene diferente grosor."],tips:["Toca el traste 5 de la cuerda 6 y luego la cuerda 5 al aire. ¿Suenan igual?"]}}},"acu-n1-l04":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Un diagrama de acorde es un dibujo del mástil visto de frente: las líneas verticales son las cuerdas (6ª a la izquierda, 1ª a la derecha) y las horizontales los trastes. Los puntos indican dónde poner los dedos y el número, qué dedo usar.",'Arriba, "o" significa cuerda al aire y "x" cuerda que no se toca.'],tips:["Compara el diagrama con tu mano frente a un espejo hasta que lo leas sin pensar."]},practica:{paragraphs:["Mi menor (Em, 022000): dedo 2 en el traste 2 de la 5ª cuerda y dedo 3 en el traste 2 de la 4ª. Se tocan las 6 cuerdas.","La menor (Am, x02210): dedo 1 en el traste 1 de la 2ª, dedo 2 en el traste 2 de la 4ª y dedo 3 en el traste 2 de la 3ª. No toques la 6ª cuerda."],tips:["Toca cada cuerda por separado para revisar que todas suenen."]},lectura:{paragraphs:['Para leer un diagrama: primero mira las "x" y "o" de arriba, luego los puntos de cada cuerda y el dedo indicado. Si aparece un número al lado (por ejemplo "5fr"), el diagrama empieza en ese traste.',"En texto, un acorde también se escribe con seis caracteres de la 6ª a la 1ª cuerda: Em = 022000, Am = x02210."],tips:["Escribe en ese formato los acordes que ya conoces."]},oido:a.s001}},"acu-n1-l05":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Las figuras musicales indican cuánto dura cada sonido. En el compás de 4/4: la redonda dura 4 tiempos, la blanca 2 tiempos y la negra 1 tiempo.",'Para leer un ritmo, cuenta los tiempos en voz alta ("1, 2, 3, 4") y sostén cada nota el número de tiempos que le toca.'],tips:["1 redonda = 2 blancas = 4 negras."]},practica:{paragraphs:["Rasguea hacia abajo una vez por tiempo (negras), contando 1-2-3-4. Mueve la muñeca, no todo el brazo, y pasa por todas las cuerdas que pide el acorde.","Practica Em y Am, 4 golpes cada uno, con el metrónomo a 60."],tips:["Con plumilla, sostenla firme pero deja que se flexione al pasar por las cuerdas."]},lectura:{paragraphs:["Así se ven las figuras: la redonda es un óvalo hueco sin plica (palito); la blanca es hueca con plica; la negra es rellena con plica.","La plica puede ir hacia arriba o hacia abajo según la posición de la nota; eso no cambia su duración."],tips:['Haz el ejercicio "Figuras rítmicas" de esta lección.']},oido:{paragraphs:["Vas a escuchar ritmos hechos con negras (y algunos silencios). Escucha con atención y repítelos tocando el botón al mismo tiempo que cuentas.","Concéntrate en el pulso: cada negra cae justo en un tiempo."],tips:['Cuenta "1, 2, 3, 4" en voz baja mientras repites el ritmo.']}}},"acu-n1-l06":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La clave de Sol se escribe al inicio del pentagrama y su espiral rodea la 2ª línea: ahí está la nota Sol. A partir de ella se leen las demás: líneas Mi–Sol–Si–Re–Fa y espacios Fa–La–Do–Mi.","La música de guitarra se escribe en clave de Sol, pero suena una octava más grave de lo escrito."],tips:['Recuerda los espacios: forman la palabra "FA-LA-DO-MI".']},practica:{paragraphs:["Re mayor (D, xx0232): dedos 1 (3ª, traste 2), 3 (2ª, traste 3) y 2 (1ª, traste 2). Toca solo 4 cuerdas.","La mayor (A, x02220): dedos 1, 2 y 3 en el traste 2 de las cuerdas 4, 3 y 2.","Mi mayor (E, 022100): como Em, más el dedo 1 en el traste 1 de la 3ª cuerda."],tips:["Con estos tres acordes puedes tocar muchas canciones en La mayor."]},lectura:{paragraphs:["La 1ª cuerda al aire es Mi. Se escribe en el cuarto espacio del pentagrama (el de hasta arriba).","Fa está en el traste 1 y se escribe en la quinta línea. Sol está en el traste 3 y se escribe en el espacio de arriba del pentagrama."],tips:["Mi = cuerda al aire, Fa = traste 1 (dedo 1), Sol = traste 3 (dedo 3).",'Haz el ejercicio "Notas en la 1ª cuerda".']},oido:{paragraphs:['La intensidad es qué tan fuerte o suave suena algo. En música se le llama dinámica: "piano" (p) es suave y "forte" (f) es fuerte.',"Controlar la fuerza de tu plumilla hace que tu música suene más expresiva."],tips:["Toca una nota muy suave y luego muy fuerte, sin cambiar de cuerda."]}}},"acu-n1-l07":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Cambiar de acorde a tiempo es la habilidad más importante del principiante. Trucos: busca dedos que se queden en su lugar (dedo guía), mueve todos los dedos a la vez y mira el siguiente acorde antes de cambiar.","Entre Em y Am, por ejemplo, los dedos 2 y 3 forman la misma figura, solo bajan una cuerda."],tips:['Practica el "minuto de cambios": cuenta cuántos cambios limpios haces en 60 segundos.']},practica:{paragraphs:["Con el metrónomo a 60, toca 4 golpes de Em y 4 de Am; luego D–A, A–E y E–Am. Si no llegas, usa el último golpe del compás para soltar el acorde y llegar al siguiente.","Sube 5 BPM cuando el cambio salga limpio 5 veces seguidas."],tips:['Es mejor que el último golpe suene "al aire" que detener el ritmo.']},lectura:{paragraphs:["La 2ª cuerda al aire es Si y se escribe en la tercera línea (la del centro).","Do está en el traste 1 y se escribe en el tercer espacio. Re está en el traste 3 y se escribe en la cuarta línea."],tips:["Si = al aire, Do = traste 1, Re = traste 3.",'Haz el ejercicio "Notas en la 2ª cuerda".']},oido:{paragraphs:['Al acompañar una canción, es importante notar cuándo cambia el acorde. Escucha la sensación de la música: cuando cambia el acorde, el "color" del sonido cambia.'],tips:["Escucha una canción y levanta la mano cada vez que sientas un cambio de acorde."]}}},"acu-n1-l08":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El cifrado americano usa letras para nombrar las notas: A = La, B = Si, C = Do, D = Re, E = Mi, F = Fa y G = Sol.",'Así se nombran también los acordes: C es Do mayor, Am es La menor (la "m" significa menor) y E5 es acorde de quinta de Mi.'],tips:["Truco: empieza en A = La y sigue el orden: La, Si, Do, Re, Mi, Fa, Sol."]},practica:{paragraphs:["Sol mayor (G, 320003): dedo 2 en el traste 3 de la 6ª, dedo 1 en el traste 2 de la 5ª y dedo 3 (o 4) en el traste 3 de la 1ª.","Do mayor (C, x32010): dedo 3 en el traste 3 de la 5ª, dedo 2 en el traste 2 de la 4ª y dedo 1 en el traste 1 de la 2ª. No toques la 6ª."],tips:["G – C – D – G es una de las progresiones más usadas en la música acústica."]},lectura:a.s002,oido:{paragraphs:["Una melodía puede subir (cada nota más aguda), bajar (cada nota más grave) o repetir la misma nota.","Reconocer esa dirección es el primer paso para sacar canciones de oído."],tips:["Mueve la mano hacia arriba o abajo siguiendo la melodía mientras escuchas."]}}},"acu-n1-l09":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Además de 4/4 existen otros compases, como 2/4 (2 tiempos) y 3/4 (3 tiempos, como en el vals). El número de arriba dice cuántos tiempos tiene cada compás.","Los silencios indican momentos sin sonido y también se cuentan. Hay silencio de redonda, de blanca, de negra y de corchea, con la misma duración que su figura.","La ligadura es una curva que une dos notas iguales: se toca solo la primera y se sostiene la duración de ambas."]},practica:{paragraphs:['Ahora rasguea abajo en cada tiempo y arriba en cada "y": 1-y-2-y-3-y-4-y. La mano sube y baja como un péndulo, constante.',"Hacia arriba basta con tocar las 3 o 4 cuerdas más agudas."],tips:["Mantén el péndulo aunque no toques en algunos golpes: así el ritmo nunca se cae."]},lectura:{paragraphs:["La corchea dura medio tiempo: dos corcheas ocupan lo mismo que una negra. Cuando van juntas se unen con una barra.",'Se cuentan "1 y 2 y 3 y 4 y": el número cae en el tiempo y la "y" en medio de dos tiempos.']},oido:{paragraphs:['Ahora los ritmos tendrán corcheas además de negras. Imagina el "y" entre cada tiempo para no perderte.'],tips:['Haz el ejercicio "Repite el ritmo con corcheas".']}}},"acu-n1-l10":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Las notas naturales de la 6ª cuerda (Mi) son: Mi (al aire), Fa (1), Sol (3), La (5), Si (7), Do (8), Re (10) y Mi otra vez (12).","En la 5ª cuerda (La): La (al aire), Si (2), Do (3), Re (5), Mi (7), Fa (8), Sol (10) y La (12).","Fíjate que entre Mi-Fa y Si-Do solo hay un traste de distancia; entre las demás notas naturales hay dos. Saber estas notas te sirve para encontrar acordes de quinta y octavas."],tips:['Prueba el juego "Encuentra la nota" en Recursos.']},practica:{paragraphs:["Toca primero la nota grave del acorde (el bajo) y luego rasguea el resto: bajo–rasgueo–bajo–rasgueo. En G el bajo es la 6ª cuerda; en C y Am, la 5ª; en D, la 4ª; en Em y E, la 6ª.","Es la base del acompañamiento en folk, country y música mexicana."],tips:["Puedes alternar dos bajos: en C, 5ª cuerda y luego 4ª (o 6ª en el traste 3)."]},lectura:{paragraphs:["En las cuerdas graves las notas se escriben abajo del pentagrama, a veces con líneas adicionales.","4ª cuerda: Re (al aire, debajo de la primera línea), Mi (traste 2, primera línea) y Fa (traste 3, primer espacio).","5ª cuerda: La (al aire), Si (2) y Do (3). 6ª cuerda: Mi (al aire), Fa (1) y Sol (3). Estas usan líneas adicionales abajo."],tips:['Haz el ejercicio "Notas en las cuerdas 4, 5 y 6".']},oido:{paragraphs:["Ahora compararás notas más cercanas entre sí. Escucha bien: ¿cuál es más grave?"]}}},"acu-n1-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El semitono es la distancia más pequeña entre dos notas en la guitarra: un traste. El tono equivale a dos semitonos: dos trastes.","Entre las notas naturales hay un tono, excepto entre Mi-Fa y Si-Do, donde hay solo un semitono."],tips:["Do-Re = tono (2 trastes). Mi-Fa = semitono (1 traste)."]},practica:{paragraphs:["La escala cromática toca todas las notas, traste por traste. El ejercicio 1-2-3-4 usa un dedo por traste: dedo 1 en el traste 1, dedo 2 en el 2, y así.","Toca 1-2-3-4 en cada cuerda, de la 6ª a la 1ª, con púa alternada y metrónomo."],tab:`e|----------------------------1-2-3-4-|
B|----------------------1-2-3-4-------|
G|----------------1-2-3-4-------------|
D|----------1-2-3-4-------------------|
A|----1-2-3-4-------------------------|
E|1-2-3-4-----------------------------|`,tips:["Deja los dedos cerca del diapasón.","Lento y limpio: cada nota debe sonar clara."]},lectura:{paragraphs:["El sostenido (♯) sube una nota un semitono; el bemol (♭) la baja un semitono. Por ejemplo, Fa♯ está un traste después de Fa.","Una misma nota puede tener dos nombres: Do♯ y Re♭ suenan igual. En la partitura, una alteración vale para todo el compás."]},oido:{paragraphs:['Un semitono suena muy "pegadito" y tenso; un tono suena un poco más abierto.'],tips:["Toca traste 1 y 2 (semitono) y luego traste 1 y 3 (tono) en la misma cuerda y compara."]}}},"acu-n1-l12":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La guitarra acústica usa cuerdas de acero (o bronce), que dan un sonido brillante y potente, pero son más duras para los dedos que las de nailon. Al principio saldrán callos: es normal; descansa si duele.","Cuidados: guárdala en su estuche, lejos del sol, del calor y de la humedad extrema; limpia las cuerdas después de tocar y cámbialas cada 2 o 3 meses (antes si suenan opacas)."],tips:["Un trapo seco después de tocar alarga mucho la vida de las cuerdas."]},practica:{paragraphs:["Es recomendable cambiar las cuerdas una por una para no perder la tensión del mástil. Después de ponerlas, estíralas suavemente y vuelve a afinar varias veces: las cuerdas nuevas se desafinan rápido.","La afinación estándar, de la 6ª a la 1ª cuerda, es: Mi, La, Re, Sol, Si, Mi (E A D G B E)."],tips:["Usa el afinador de la app.","Afina siempre subiendo hacia la nota: si te pasas, baja un poco y vuelve a subir."]},lectura:{paragraphs:["Repaso: vas a leer una melodía de 8 compases con todas las notas y ritmos que aprendiste en este nivel.","Antes de tocar, revisa el compás, busca las notas difíciles y cuenta el ritmo con palmas."]},oido:{paragraphs:["Puedes afinar comparando cuerdas: el traste 5 de una cuerda suena igual que la siguiente cuerda al aire. La excepción es la 3ª cuerda: su traste 4 suena igual que la 2ª al aire.",'Cuando dos notas están casi afinadas, escucharás una especie de "vibración" (batimiento). Mientras más lenta, más cerca estás de la afinación.'],tips:['Haz el ejercicio "¿Afinado o desafinado?".']}}},"acu-n2-l01":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Mayor: fundamental, tercera mayor y quinta (suena brillante). Menor: con tercera menor (suena más oscuro). Séptima de dominante: mayor más la séptima menor (suena tenso y pide resolver).","Ejemplo en La: A (La–Do♯–Mi), Am (La–Do–Mi), A7 (La–Do♯–Mi–Sol)."],tips:["Toca A, Am y A7 seguidos y describe cómo suena cada uno."]},practica:{paragraphs:["E7 (020100): como E, levantando el dedo de la 4ª cuerda. A7 (x02020): como A sin el dedo de la 3ª. D7 (xx0212). G7 (320001).","Resoluciones típicas: E7 → A, A7 → D, D7 → G, G7 → C."],tips:['Toca G – G7 – C y escucha cómo el G7 "empuja" hacia Do.']},lectura:a.s003,oido:{paragraphs:["El acorde mayor suena estable; el de séptima, con una tensión que pide moverse. Escucha y decide cuál es cuál."],tips:["Si después del acorde sientes ganas de que siga la música, probablemente era de séptima."]}}},"acu-n2-l02":{status:"borrador",generated:!0,sections:{teoria:a.s004,practica:{paragraphs:["El patrón más famoso del pop acústico: 1 (abajo), 2 (abajo), y (arriba), [3 sin tocar], y (arriba), 4 (abajo), y (arriba). La mano sigue moviéndose en el tiempo 3, sin tocar.","Practícalo sobre G – D – Em – C."],tips:['Dilo en voz alta: "a-ba-jo, a-ba-jo-ar-ri-ba, ___, ar-ri-ba-a-ba-jo-ar-ri-ba".']},lectura:{paragraphs:['Los patrones de rasgueo se escriben con flechas (↓ abajo, ↑ arriba) o letras (A = abajo, R = arriba / D y U en inglés) bajo los números de los tiempos. Un espacio vacío significa "la mano pasa sin tocar".'],tips:["Escribe el rasgueo pop con flechas: ↓ ↓↑ _↑ ↓↑."]},oido:{paragraphs:["Escucha un rasgueo y cuenta 1-y-2-y-3-y-4-y: ¿en qué golpes suena la guitarra? Así puedes copiar el patrón de una canción."],tips:["Imita el rasgueo con la mano en el aire antes de tomar la guitarra."]}}},"acu-n2-l03":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['La guitarra de cuerdas de acero nació en Estados Unidos a finales del siglo XIX y comienzos del XX. Fabricantes como C. F. Martin y Gibson reforzaron la tapa con varetas en "X" para soportar la tensión del acero. En 1916 Martin creó el modelo dreadnought, grande y potente, que hoy es el más común.',"Se volvió el instrumento del folk, el country, el blues y el cantautor: Woody Guthrie, Bob Dylan, Joni Mitchell, y en Latinoamérica la trova y el bolero."],tips:["Escucha un blues acústico antiguo y una canción folk de los 60 para comparar estilos."]},practica:{paragraphs:["El chuck es un golpe percusivo: al rasguear hacia abajo, apoya la palma (o el canto de la mano) sobre las cuerdas para que suenen secas, como una caja de batería. Suele ir en los tiempos 2 y 4.","Patrón: abajo, chuck, abajo-arriba, chuck-arriba."],tips:["Practica primero solo el chuck hasta que suene seco y parejo."]},lectura:{paragraphs:["El acento (>) sobre una nota o un golpe indica tocarlo más fuerte. En el rasgueo, acentuar ciertos golpes da carácter: en el pop se acentúan 2 y 4; en el reggae, los contratiempos."],tips:["Rasguea corcheas y acentúa solo los tiempos 2 y 4."]},oido:a.s005}},"acu-n2-l04":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El capo es una abrazadera que presiona todas las cuerdas en un traste, subiendo el tono de la guitarra. Con capo en el traste 2, las formas de G suenan como La; en el 3, como Si♭.","Se usa para adaptar una canción a la voz sin aprender acordes nuevos. Colócalo justo detrás del traste y vuelve a afinar si hace falta."],tips:["Cada traste de capo sube medio tono."]},practica:{paragraphs:["Toca G – C – D – G sin capo, luego con capo en el traste 2 (suena A – D – E – A) y en el 5 (suena C – F – G – C). Canta encima y elige el traste más cómodo para tu voz."],tips:["Anota en tu cancionero el traste de capo que usas en cada canción."]},lectura:{paragraphs:['Las canciones con capo se escriben indicando "Capo 2" (o el traste) arriba y los acordes en las formas que tocas. Por ejemplo, "Capo 3: G – Em – C – D" suena en Si♭ – Sol menor – Mi♭ – Fa.'],tips:['Si alguien te da los acordes "reales", resta el capo para encontrar las formas.']},oido:{paragraphs:["Escucha una progresión y luego la misma más aguda o más grave. La relación entre los acordes no cambia: solo la altura."],tips:["Canta la primera nota de cada versión para comparar."]}}},"acu-n2-l05":{status:"borrador",generated:!0,sections:{teoria:a.s006,practica:{paragraphs:["Sol mayor: Sol–La–Si–Do–Re–Mi–Fa♯–Sol. En primera posición: 6ª (3), 5ª (0, 2, 3), 4ª (0, 2, 4), 3ª (0)."],tips:["El Fa♯ está en el traste 4 de la 4ª cuerda: úsalo con el dedo 4."],tab:`e|---------------|
B|---------------|
G|-------------0-|
D|-------0-2-4---|
A|-0-2-3---------|
E|3--------------|`},lectura:a.s007,oido:a.s008}},"acu-n2-l06":{status:"borrador",generated:!0,sections:{teoria:a.s009,practica:{paragraphs:["La cejilla parcial presiona solo 2 o 3 cuerdas con el dedo 1. Fa mayor pequeño (xx3211): dedo 1 en el traste 1 de las cuerdas 1 y 2, dedo 2 en la 3ª (traste 2), dedo 3 en la 4ª (traste 3).","Si menor pequeño (xx4432): dedo 1 en el traste 2 de las cuerdas 1 y 2, dedo 3 y 4 en el traste 4 de la 4ª y 3ª."],tips:["Gira un poco el dedo 1 hacia el borde para que presione con la parte dura."]},lectura:a.s010,oido:a.s011}},"acu-n2-l07":{status:"borrador",generated:!0,sections:{teoria:a.s012,practica:{paragraphs:["Vals (3/4): bajo en el 1 y rasgueo en el 2 y 3 (bajo–acorde–acorde). Balada en 6/8: abajo, abajo, arriba, abajo, abajo, arriba, acentuando el 1 y el 4."],tips:["Practica el vals con G – D – D – G y la balada 6/8 con C – Am – F – G."]},lectura:a.s012,oido:a.s013}},"acu-n2-l08":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Cantar y tocar requiere que el rasgueo sea automático. Pasos: domina el rasgueo y los cambios; luego tararea la melodía mientras tocas; después di la letra en ritmo; al final, canta.","Si te pierdes, simplifica el rasgueo (solo negras) hasta que la voz vaya segura."],tips:["Empieza con canciones de pocos acordes y melodía sencilla."]},practica:{paragraphs:["Elige una canción con G, C, D y Em. Toca el rasgueo sin cantar 4 veces, luego canta solo el coro, y después toda la canción."],tips:["Grábate: verás si la voz y la guitarra van juntas."]},lectura:{paragraphs:['En un cancionero, el acorde se escribe encima de la sílaba en la que cambia. Si un acorde está sobre "can-", cambia justo cuando cantas esa sílaba.'],tips:["Lee la letra en voz alta marcando con la mano dónde cambia el acorde."]},oido:{paragraphs:["Antes de cantar, busca en la guitarra la primera nota de la melodía (a menudo es una nota del primer acorde). Tócala, cántala y luego empieza."],tips:["Si la canción empieza en Sol, la nota de inicio suele ser Sol, Si o Re."]}}},"acu-n2-l09":{status:"borrador",generated:!0,sections:{teoria:a.s014,practica:{paragraphs:['En semicorcheas hay 4 golpes por tiempo: "1-i-y-a". La mano baja en "1" y "y" y sube en "i" y "a". Se usa en funk, pop rápido y música latina.',"Empieza tocando todos los golpes muy suave y luego quita algunos para crear patrones."],tips:["Metrónomo a 50–60 BPM; la mano debe ir relajada."]},lectura:a.s015,oido:a.s016}},"acu-n2-l10":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En la cejilla completa, el dedo 1 presiona las 6 cuerdas en un traste y los demás dedos forman un acorde abierto movido. Permite tocar cualquier acorde mayor o menor.","Coloca el dedo 1 recto y cerca del traste, usa el peso del brazo y no aprietes de más con el pulgar."],tips:["Con cuerdas de acero cuesta más: empieza en el traste 5 o 7, donde la cuerda está más baja."]},practica:{paragraphs:["Forma de Mi (en la 6ª cuerda): F = 133211, Fm = 133111, G = 355433. Forma de La (en la 5ª): B♭ = x13331, Bm = x24432, C = x35553.","La nota de la 6ª o la 5ª cuerda en el traste de la cejilla da el nombre al acorde."],tips:["Practica F – Bm – C – G alternando ambas formas."]},lectura:a.s017,oido:a.s018}},"acu-n2-l11":{status:"borrador",generated:!0,sections:{teoria:a.s019,practica:a.s020,lectura:a.s021,oido:a.s022}},"acu-n2-l12":{status:"borrador",generated:!0,sections:{teoria:a.s023,practica:{paragraphs:["Blues de 12 compases en Mi: E7 (4) – A7 (2) – E7 (2) – B7 (1) – A7 (1) – E7 (2). Con el pulgar alterna los bajos (6ª y 4ª en E7; 5ª y 4ª en A7) y con los dedos toca las cuerdas agudas.","B7 = x21202."],tips:["Escucha a Big Bill Broonzy o Mississippi John Hurt: maestros del blues acústico."]},lectura:a.s024,oido:a.s025}},"acu-n3-l01":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En el fingerstyle, los dedos de la mano derecha se nombran con letras del español: p (pulgar), i (índice), m (medio) y a (anular). El meñique casi no se usa.","Regla básica: el pulgar toca los bajos (cuerdas 6, 5 y 4) y i, m, a las cuerdas 3, 2 y 1."],tips:["Apoya ligeramente el antebrazo en el borde de la caja y deja la mano suelta sobre la boca."]},practica:{paragraphs:["Sobre C: p en la 5ª, i en la 3ª, m en la 2ª, a en la 1ª. Sobre G y Em, el pulgar va a la 6ª; sobre D, a la 4ª."],tips:["Mantén el acorde presionado completo aunque toques nota por nota."],tab:`e|-------0-------|
B|-----1---------|
G|---0-----------|
D|---------------|
A|-3-------------|
E|---------------|`},lectura:{paragraphs:["En partituras y tablaturas, las letras p, i, m, a aparecen sobre o bajo las notas para indicar qué dedo de la mano derecha toca. Los números (1-4) indican los dedos de la mano izquierda."],tips:["No confundas: letras = mano derecha, números = mano izquierda."]},oido:a.s026}},"acu-n3-l02":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Patrones comunes: p-i-m-a (subiendo), p-a-m-i (bajando), p-i-m-a-m-i (ida y vuelta), y p-i-m-i en grupos de cuatro. En 3/4 se usa p-i-m-a-m-i o p-(im)-(im).","Cada patrón da un carácter distinto a la misma progresión."],tips:["Toca C – Am – F – G con tres patrones distintos."]},practica:{paragraphs:["En 4/4: p-i-m-a-m-i-m-i (8 corcheas). En 3/4: p-i-m-a-m-i (6 corcheas). Prueba C – G – Am – F en 4/4 y G – D – C – G en 3/4."],tips:["Cuenta en voz alta para que el pulgar caiga siempre en el tiempo 1."]},lectura:{paragraphs:["En tablatura, el arpegio se ve como números escalonados en diferentes cuerdas, uno tras otro. A veces se agrega la letra del dedo (p, i, m, a) debajo."],tips:["Identifica el acorde mirando todos los números del compás juntos."]},oido:{paragraphs:["Escucha si el arpegio sube, baja o va de ida y vuelta, y cuántas notas hay por tiempo."],tips:["Imita el patrón tocando las cuerdas al aire."]}}},"acu-n3-l03":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En el bajo alternado, el pulgar alterna dos notas graves del acorde en cada tiempo: la fundamental y otra nota (normalmente la quinta). En C: 5ª cuerda (Do) y 4ª (Mi) o 6ª traste 3 (Sol). En G: 6ª (Sol) y 4ª (Re). En D: 4ª (Re) y 5ª al aire (La).","Es la base del fingerstyle folk, country y blues."],tips:["El pulgar debe sonar parejo como un metrónomo."]},practica:{paragraphs:["Toca solo bajos en negras: en C, 5ª–4ª–5ª–4ª (o 5ª–4ª–6ª–4ª). Luego agrega las cuerdas agudas con i y m entre los bajos."],tips:["Practica solo el pulgar hasta que salga sin pensar."]},lectura:{paragraphs:["En una tablatura de fingerstyle, los bajos suelen escribirse con plicas hacia abajo y la melodía hacia arriba. Los números en las cuerdas graves son el bajo; los de las agudas, la melodía o el relleno."],tips:["Lee primero solo los bajos y luego agrega lo demás."]},oido:a.s027}},"acu-n3-l04":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El travis picking (por Merle Travis) es un patrón en el que el pulgar alterna bajos de forma constante, en todos los tiempos, mientras los dedos tocan notas agudas entre los bajos (en los contratiempos). Crea la sensación de dos guitarras a la vez.","Lo usaron Chet Atkins, James Taylor, Paul Simon y muchos más."],tips:["El secreto es que el pulgar nunca se detenga."]},practica:{paragraphs:['Sobre C (x32010), un patrón básico en corcheas: p (5ª) – i (2ª) – p (4ª) – m (1ª) – p (5ª) – i (2ª) – p (4ª) – m (1ª). El pulgar cae en cada tiempo y los dedos en los "y".'],tips:["Cuando salga fluido, alterna el bajo de la 5ª con la 6ª cuerda en el traste 3 (Sol)."],tab:`e|-------0-------0-|
B|---1-------1-----|
G|-----------------|
D|-----2-------2---|
A|-3-------3-------|
E|-----------------|`},lectura:{paragraphs:["Busca primero los bajos del pulgar (cada tiempo) y luego las notas agudas intercaladas. En la partitura, el pulgar suele llevar plicas hacia abajo."],tips:["Toca muy lento las dos manos marcando en voz alta qué dedo va."]},oido:{paragraphs:["Con pulgar constante, los bajos suenan en cada tiempo sin parar (como en el travis picking). Con pulgar libre, los bajos aparecen solo en algunos momentos. Escucha y decide."],tips:["Marca el pulso con el pie y fíjate si cada golpe tiene un bajo."]}}},"acu-n3-l05":{status:"borrador",generated:!0,sections:{teoria:a.s028,practica:{paragraphs:["Agrega hammer-ons y pull-offs dentro de un arpegio para darle movimiento: en C, toca la 3ª cuerda al aire y haz hammer-on al traste 2; en Am, pull-off de la 2ª cuerda del traste 1 al aire."],tips:["El ligado debe sonar al mismo volumen que las notas pulsadas."]},lectura:a.s029,oido:a.s030}},"acu-n3-l06":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['El slide desliza el dedo de un traste a otro sin soltar la cuerda; el hammer-on y el pull-off ligan notas; el vibrato hace que una nota "tiemble". Todos se usan para adornar melodías y acompañamientos.'],tips:["Adorna poco: un adorno en el momento justo vale más que muchos."]},practica:{paragraphs:["Toma una melodía sencilla y agrega un slide para llegar a la primera nota, un hammer-on en medio y vibrato al final."],tips:["Graba la melodía con y sin adornos y compara."]},lectura:{paragraphs:['En tablatura, el slide se escribe con / (subiendo) o \\ (bajando) entre números: 5/7 o 7\\5. A veces aparece "sl.". Un slide desde una nota indefinida se escribe /7.'],tips:["Lee y toca: 0 – 2/4 – 4\\2 – 0."]},oido:a.s031}},"acu-n3-l07":{status:"borrador",generated:!0,sections:{teoria:a.s032,practica:{paragraphs:["Practica arpegios sobre las progresiones típicas de cada tono: Sol (G – C – D – G), Re (D – G – A – D) y Do (C – F – G – C). El pulgar busca la cuerda del bajo de cada acorde."],tips:["Usa el patrón p-i-m-a-m-i y mantenlo en los tres tonos."]},lectura:a.s033,oido:a.s034}},"acu-n3-l08":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:['Un acorde "con bajo" (slash chord) toca un acorde con una nota distinta en el bajo. Se escribe Acorde/Bajo: C/G es Do mayor con Sol en el bajo.',"Sirven para crear líneas de bajo que bajan o suben suavemente entre acordes."],tips:["G – D/F♯ – Em es una línea de bajo descendente muy común."]},practica:{paragraphs:["C/G (332010): Do con el dedo 4 en el traste 3 de la 6ª. D/F♯ (2x0232): Re con el pulgar o el dedo 2 en el traste 2 de la 6ª. G/B (x20003): Sol con Si en la 5ª.","Practica G – D/F♯ – Em – C y C – G/B – Am."],tips:["En D/F♯, no toques la 5ª cuerda."]},lectura:{paragraphs:["La barra indica el bajo: D/F♯ = acorde de Re con Fa♯ en el bajo. Lo de la izquierda es el acorde; lo de la derecha, la nota más grave."],tips:["No confundas D/F♯ con un acorde de Fa♯."]},oido:{paragraphs:["Escucha la nota más grave del acorde y canta esa nota. Así sabrás si el acorde está en posición fundamental o tiene otro bajo."],tips:["Concéntrate en las cuerdas graves."]}}},"acu-n3-l09":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En el fingerstyle, el pulgar toca el bajo y los dedos la melodía en las cuerdas agudas, al mismo tiempo. Así una sola guitarra suena como dos instrumentos.","Empieza con melodías lentas y bajos en negras."],tips:["Haz que la melodía suene un poco más fuerte que el bajo."]},practica:{paragraphs:['Arregla 8 compases de una canción sencilla ("Cielito lindo", "Las mañanitas"): la melodía en las cuerdas 1-2-3 y el bajo de cada acorde con el pulgar en el tiempo 1 (o en los tiempos 1 y 3).'],tips:["Escribe tu arreglo en tablatura a medida que lo creas."]},lectura:a.s035,oido:a.s036}},"acu-n3-l10":{status:"borrador",generated:!0,sections:{teoria:a.s037,practica:{paragraphs:["Toca frases cortas con la escala mayor o la pentatónica en las cuerdas agudas, como pequeñas introducciones o puentes entre partes de una canción."],tips:["Termina la frase en una nota del acorde que sigue."]},lectura:a.s038,oido:a.s039}},"acu-n3-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En un ensamble, la guitarra acústica suele llevar el ritmo y la armonía. Si hay bajo, no hace falta tocar los bajos tan fuertes; si hay otra guitarra, una puede rasguear y la otra arpegiar o usar capo en otra posición."],tips:["Busca un registro distinto al de los demás instrumentos."]},practica:{paragraphs:["Practica con pistas de voz, bajo y percusión. Escucha el bombo para el ritmo y la voz para la dinámica: toca más suave en el verso y más lleno en el coro."],tips:["Deja espacio a la voz: no rasguees fuerte cuando canta."]},lectura:{paragraphs:["Una parte de guitarra acompañante muestra los acordes, el ritmo (con barras o figuras rítmicas) y la forma de la canción. Puede indicar capo, rasgueo o arpegio."],tips:["Marca las repeticiones y los cambios de sección."]},oido:{paragraphs:["Escucha una canción e identifica: el bajo (grave), la guitarra (medio, rasgueada o punteada) y la percusión (golpes sin altura definida)."],tips:["Concéntrate en un instrumento a la vez."]}}},"acu-n3-l12":{status:"borrador",generated:!0,sections:{teoria:a.s040,practica:a.s041,lectura:a.s042,oido:a.s043}},"acu-n4-l01":{status:"borrador",generated:!0,sections:{teoria:a.s044,practica:a.s045,lectura:a.s046,oido:a.s047}},"acu-n4-l02":{status:"borrador",generated:!0,sections:{teoria:a.s048,practica:{paragraphs:["Para cambiar el tono de una canción sin cambiar las formas de los acordes, usa el capo: cada traste sube medio tono. Para bajar, toca formas más graves y usa capo para ajustar.","Ejemplo: canción en G demasiado grave → capo 2 (suena en A) o capo 4 (suena en B)."],tips:["Prueba la canción con capo en varios trastes y elige el que mejor quede a la voz."]},lectura:a.s049,oido:a.s050}},"acu-n4-l03":{status:"borrador",generated:!0,sections:{teoria:a.s051,practica:a.s052,lectura:a.s053,oido:a.s054}},"acu-n4-l04":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La balada es una canción lenta y romántica, con melodía expresiva y acompañamiento suave. En español es un estilo muy popular (José José, Camilo Sesto, Luis Miguel, y hoy artistas pop). En la acústica se acompaña con arpegios o rasgueos suaves, a menudo en 4/4 o 6/8."],tips:["Escucha cómo la guitarra crece del verso al coro."]},practica:{paragraphs:["Verso con arpegio p-i-m-a-m-i, coro con rasgueo suave abajo, abajo-arriba, arriba-abajo-arriba. Prueba C – G/B – Am – F – G."],tips:["Usa la dinámica para que el coro destaque."]},lectura:{paragraphs:["Una guía de acordes muestra letra, acordes y, a veces, el patrón sugerido. Busca la forma: introducción, verso, coro, puente."],tips:["Marca con colores las secciones."]},oido:a.s055}},"acu-n4-l05":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El bolero nació en Cuba a fines del siglo XIX y se volvió un estilo emblemático en México, con tríos como Los Panchos y compositores como Agustín Lara y Armando Manzanero. Se toca en 4/4 con un ritmo característico y una guitarra requinto que hace introducciones y adornos."],tips:["Escucha a Los Panchos para oír el requinto y la guitarra de ritmo."]},practica:{paragraphs:['Ritmo básico de bolero (guitarra de ritmo): bajo en el 1, rasgueo en el "y" del 2 y en el 3, bajo en el 4 (o variantes con pulgar y dedos). El requinto toca terceras y frases melódicas en las cuerdas agudas.',"Practica Am – Dm – E7 – Am."],tips:["Practica primero el ritmo lento con metrónomo."]},lectura:{paragraphs:["El ritmo de bolero se escribe en 4/4 con negras, corcheas y contratiempos. El patrón básico (bolero rítmico) se basa en: negra, corchea con puntillo y semicorchea, y dos negras, o en la variante del cinquillo cubano."],tips:["Lee el ritmo con palmas antes de tocarlo."]},oido:a.s056}},"acu-n4-l06":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La ranchera es un género mexicano que se toca principalmente en tres ritmos: vals (3/4), polka (2/4) y bolero ranchero (4/4). La guitarra alterna bajo y acorde con fuerza. Referentes: José Alfredo Jiménez, Vicente Fernández, Pedro Infante."],tips:['Escucha "El Rey" de José Alfredo Jiménez y fíjate en el ritmo.']},practica:{paragraphs:["Vals ranchero (3/4): bajo–acorde–acorde. Polka (2/4): bajo–acorde–bajo alterno–acorde (en corcheas). Practica G – D7 – G en ambos ritmos."],tips:["Alterna los bajos: en G, 6ª y 4ª cuerda; en D7, 4ª y 5ª."]},lectura:{paragraphs:["En 3/4: negra (bajo) y dos negras (acorde). En 2/4: corcheas alternando bajo y acorde. Lee con palmas y luego con la guitarra."],tips:["Acentúa el bajo."]},oido:a.s057}},"acu-n4-l07":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El son es una familia de géneros tradicionales: el son cubano, y en México el son jarocho (Veracruz), el huasteco o huapango y el son jalisciense. Usan ritmos con sesquiáltera (alternancia entre 6/8 y 3/4) y, en el caso cubano, la clave.","En la guitarra acústica se adaptan con rasgueos acentuados y apagados."],tips:['Escucha "La Bamba" (son jarocho) y un huapango como "Cielito lindo huasteco".']},practica:{paragraphs:["Huapango básico: en 6/8 alterna acentos en grupos de 3 y 2 (sesquiáltera): abajo-arriba-abajo con acentos en 1, 3 y 5 en un compás y 1 y 4 en el siguiente. Son: rasgueos acentuados con apagados en contratiempos.","Practica D – A7 – D (huapango) y C – G7 – C (son)."],tips:['Empieza muy lento contando "1-2-3-4-5-6".']},lectura:a.s058,oido:{paragraphs:["La clave es un patrón de 5 golpes en dos compases (3-2 o 2-3). El sesquiáltero alterna la sensación de 2 grupos de 3 y 3 grupos de 2. Escucha y decide qué se oye."],tips:["Aplaude la clave mientras escuchas un son cubano."]}}},"acu-n4-l08":{status:"borrador",generated:!0,sections:{teoria:a.s059,practica:{paragraphs:["Las terceras son dos notas a distancia de tercera (Do–Mi, Re–Fa…); las sextas, a distancia de sexta (Mi–Do, Fa–Re…). En la guitarra se tocan en pares de cuerdas: terceras en las cuerdas 2-3 y sextas en las cuerdas 1-3 (saltando la 2ª).","Son la base del requinto en el bolero y los adornos de la música mexicana."],tips:["Toca la escala de Do en terceras en las cuerdas 2 y 3."]},lectura:{paragraphs:["En el pentagrama, una tercera se ve como dos notas en líneas consecutivas (o espacios consecutivos); una sexta, como dos notas separadas por varias líneas. Se cuentan las notas de abajo hacia arriba incluyendo ambas."],tips:["Do–Mi = tercera (Do, Re, Mi); Do–La = sexta."]},oido:{paragraphs:["La tercera suena dulce y cercana; la sexta, amplia y cálida. Escucha dos notas a la vez y decide si es una tercera o una sexta."],tips:["Las terceras son el sonido típico de los dúos de voces mexicanos."]}}},"acu-n4-l09":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Al construir un acorde sobre cada nota de la escala mayor, usando solo notas de la escala, se obtiene la escala armonizada: I mayor, ii menor, iii menor, IV mayor, V mayor, vi menor, vii disminuido.","En Sol: G, Am, Bm, C, D, Em, F♯dim. En Do: C, Dm, Em, F, G, Am, Bdim."],tips:['Con esta lista puedes saber qué acordes "pertenecen" a una canción.']},practica:a.s060,lectura:a.s061,oido:a.s062}},"acu-n4-l10":{status:"borrador",generated:!0,sections:{teoria:a.s063,practica:a.s064,lectura:a.s065,oido:a.s066}},"acu-n4-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Un acorde de paso conecta dos acordes de forma suave, normalmente con un bajo que se mueve por pasos. Un cromatismo usa notas a medio tono de distancia. Por ejemplo, de C a Am pasando por G/B (bajo Do–Si–La)."],tips:["Los bajos de paso hacen que la guitarra suene más profesional."]},practica:{paragraphs:["Entre G y C: toca Sol (6ª, 3), La (5ª, 0), Si (5ª, 2) y llega a Do (5ª, 3). Entre C y G: Do, Si, La, Sol. Entre G y Em: Sol, Fa♯, Mi."],tips:["Toca el bajo de paso en el último tiempo del compás."],tab:`e|---------------|
B|---------------|
G|---------------|
D|---------------|
A|-----0-2-3-----|
E|-3-------------|`},lectura:{paragraphs:["En la tablatura o la partitura, los bajos de paso aparecen como notas sueltas en las cuerdas graves entre dos acordes. En el cifrado se escriben a veces como acordes con bajo (G – G/B – C)."],tips:["Fíjate en la dirección del bajo: sube o baja."]},oido:{paragraphs:["Escucha una línea de bajo entre dos acordes y decide si sube o baja."],tips:["Canta la línea del bajo para sentir su dirección."]}}},"acu-n4-l12":{status:"borrador",generated:!0,sections:{teoria:a.s067,practica:{paragraphs:["Elige un género que te guste y estudia sus tres pilares en la guitarra acústica: el patrón rítmico típico, las progresiones o acordes característicos y el tipo de sonido (limpio, saturado, con efectos o acústico).","Practica cada pilar por separado y luego toca una canción completa del género."],tips:["Escucha la canción con atención antes de tocarla: copiar el sonido es parte del estudio."]},lectura:a.s068,oido:a.s069}},"acu-n5-l01":{status:"borrador",generated:!0,sections:{teoria:a.s070,practica:{paragraphs:["En drop D, la 6ª cuerda baja un tono, de Mi a Re (afinación Re–La–Re–Sol–Si–Mi). Así las tres cuerdas graves al aire forman un acorde de Re con quinta, ideal para canciones en Re con un bajo profundo.","Arreglo sencillo en Re: bajo en la 6ª al aire con el pulgar y acordes D (xx0232), G (5x0433 o x55433 con cejilla) y A en la parte aguda."],tips:["Afina la 6ª cuerda comparándola con la 4ª al aire: deben sonar a una octava."]},lectura:{paragraphs:['Las tablaturas en afinaciones alternas indican la afinación al inicio (por ejemplo "Drop D: D A D G B E"). Los números siguen siendo trastes, pero las notas cambian según la afinación.'],tips:["Revisa siempre la afinación indicada antes de tocar una TAB."]},oido:{paragraphs:["En drop D, la nota más grave suena un tono más grave y profunda. Escucha y decide si la guitarra está en afinación estándar o en drop D."],tips:["Fíjate en el bajo más grave del acorde final."]}}},"acu-n5-l02":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En una afinación abierta, las cuerdas al aire forman un acorde. Open G: Re–Sol–Re–Sol–Si–Re (acorde de Sol); muy usada en blues y rock (Keith Richards). DADGAD: Re–La–Re–Sol–La–Re, un sonido suspendido usado en música celta y fingerstyle moderno.","Con un dedo en cejilla puedes formar acordes mayores en Open G."],tips:["Cambia de afinación con calma y revisa con el afinador."]},practica:{paragraphs:["En Open G, una cejilla en el traste 5 da Do y en el 7, Re: con Sol al aire, el traste 5 y el 7 tienes I, IV y V. Toca melodías en las cuerdas agudas dejando sonar las cuerdas al aire."],tips:["Las cuerdas al aire resonando son el encanto de estas afinaciones."]},lectura:{paragraphs:['Los diagramas en afinación abierta llevan arriba la afinación (por ejemplo "DGDGBD"). Las formas de acorde son distintas a las de la afinación estándar.'],tips:["No uses diagramas de afinación estándar en una afinación abierta."]},oido:{paragraphs:["Las cuerdas al aire que resuenan dan un sonido amplio, como de arpa. Escucha y decide si el acorde deja cuerdas al aire sonando."],tips:['Fíjate en la "cola" de sonido después del ataque.']}}},"acu-n5-l03":{status:"borrador",generated:!0,sections:{teoria:a.s071,practica:{paragraphs:["Los armónicos naturales se tocan rozando la cuerda (sin presionar) justo encima de los trastes 12, 7 o 5 y soltando al pulsar: suenan como campanitas. Los artificiales se hacen presionando una nota y rozando 12 trastes más arriba con el índice derecho mientras pulsas con el pulgar o el anular."],tips:["Toca el armónico del traste 12 en las seis cuerdas: deben sonar claros y largos."]},lectura:a.s072,oido:a.s073}},"acu-n5-l04":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En el fingerstyle moderno, la guitarra acústica también es percusión: golpes con el pulgar o la palma en la caja (como bombo), golpes con los dedos en las cuerdas (como caja o tarola) y slaps. Referentes: Andy McKee, Tommy Emmanuel, Sungha Jung."],tips:["Golpea cerca del puente para un sonido grave y en el borde superior para un sonido agudo."]},practica:{paragraphs:["Patrón básico: golpe con el pulgar o la base de la palma en la caja en el tiempo 1 y 3 (bombo) y slap con los dedos sobre las cuerdas en el 2 y 4 (caja). Luego agrega acordes entre golpes."],tips:["Cuida tu guitarra: golpea con la parte blanda de la mano, no con anillos ni uñas."]},lectura:a.s074,oido:{paragraphs:["El golpe percusivo suena seco y sin notas definidas; el rasgueo, con notas del acorde. Escucha y decide."],tips:["Fíjate si se oyen notas o solo un golpe."]}}},"acu-n5-l05":{status:"borrador",generated:!0,sections:{teoria:a.s075,practica:a.s076,lectura:a.s077,oido:a.s078}},"acu-n5-l06":{status:"borrador",generated:!0,sections:{teoria:a.s079,practica:{paragraphs:["Cmaj7 (x32000), Am7 (x02010), Em7 (022030), Dmaj7 (xx0222), Cadd9 (x32030), Dsus4 (xx0233), Asus4 (x02230). Suenan más abiertos y modernos que los acordes básicos.","Prueba G – Cadd9 – Em7 – Dsus4: un clásico del pop acústico."],tips:["En G – Cadd9 los dedos 3 y 4 se quedan quietos en la 2ª y 1ª cuerdas (traste 3)."]},lectura:{paragraphs:["maj7 = séptima mayor; m7 = menor con séptima; add9 = se agrega la novena (con tercera); sus4 = la cuarta sustituye a la tercera; sus2 = la segunda sustituye a la tercera."],tips:["Cadd9 tiene tercera (Mi); Csus2 no."]},oido:a.s080}},"acu-n5-l07":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Un arreglo para guitarra sola incluye melodía, bajo y armonía en un solo instrumento. Pasos: elige un tono cómodo (muchas veces Re, Sol, La o Mi para usar cuerdas al aire), pon la melodía en las cuerdas agudas, el bajo con el pulgar y rellena con notas del acorde."],tips:["Prioriza la melodía: si una nota del acorde estorba, quítala."]},practica:{paragraphs:["Arregla 8 compases: melodía en las cuerdas 1-3, bajo alternado o en el tiempo 1 con el pulgar, y notas de acorde cuando la melodía descansa."],tips:["Escribe el arreglo en tablatura mientras lo construyes."]},lectura:a.s081,oido:a.s082}},"acu-n5-l08":{status:"borrador",generated:!0,sections:{teoria:a.s083,practica:{paragraphs:["Toca un arpegio p-i-m-a-m-i sobre C – Am – F – G con metrónomo. Empieza a 60 BPM en corcheas, sube a semicorcheas y aumenta 4 BPM cada vez que salga limpio."],tips:["Si se tensa la mano, baja el tempo."]},lectura:a.s084,oido:a.s085}},"acu-n5-l09":{status:"borrador",generated:!0,sections:{teoria:a.s086,practica:{paragraphs:["Formas útiles: Dm7 (xx0211) – G7 (320001) – Cmaj7 (x32000) en Do; Am7 (x02010) – D7 (xx0212) – Gmaj7 (3x0002) en Sol; Em7 (022030) – A7 (x02020) – Dmaj7 (xx0222) en Re."],tips:["Toca cada II–V–I con un rasgueo suave de bossa o swing."]},lectura:a.s087,oido:a.s088}},"acu-n5-l10":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["La bossa nova nació en Brasil a finales de los 50 con João Gilberto, Antonio Carlos Jobim y Vinicius de Moraes. Combina la samba con armonías de jazz (maj7, m7, 9) y se toca con los dedos: el pulgar marca un bajo constante y los dedos tocan acordes sincopados."],tips:['Escucha "Garota de Ipanema" y fíjate en la guitarra.']},practica:{paragraphs:['El pulgar toca el bajo en los tiempos 1 y 2 (alternando fundamental y quinta en 2/4 o en los tiempos 1-3 en 4/4). Los dedos i-m-a tocan el acorde en un patrón sincopado: en el 1, el "y" del 1, el "y" del 2… hasta completar un patrón de dos compases.',"Practica con Am7 – D7 – Gmaj7."],tips:["Empieza solo con el pulgar y agrega los dedos poco a poco."]},lectura:{paragraphs:["El ritmo de bossa se escribe en 2/4 o 4/4 con corcheas y síncopas ligadas. El bajo va con plicas hacia abajo y el acorde con plicas hacia arriba."],tips:["Lee el patrón con palmas: una mano para el bajo y otra para los acordes."]},oido:a.s089}},"acu-n5-l11":{status:"borrador",generated:!0,sections:{teoria:a.s090,practica:a.s091,lectura:a.s092,oido:a.s093}},"acu-n5-l12":{status:"borrador",generated:!0,sections:{teoria:a.s094,practica:{paragraphs:["Graba una maqueta de 1 minuto de guitarra y voz: primero la guitarra con metrónomo y después la voz, o ambas juntas con un solo micrófono. Usa el celular o un DAW."],tips:["Terminar es más importante que la perfección."]},lectura:a.s095,oido:a.s096}},"acu-n6-l01":{status:"borrador",generated:!0,sections:{teoria:a.s097,practica:{paragraphs:["Antes de empezar el proyecto final, repasa lo más importante del curso en la guitarra acústica: técnica, acordes, escalas, ritmos y las canciones que ya sabes. Detecta qué te cuesta y dedica tiempo extra a eso.","Arma una rutina de 20 minutos: 5 de calentamiento, 10 de técnica y 5 de una canción."],tips:["Haz una lista de los temas que dominas y los que necesitas reforzar."]},lectura:a.s098,oido:a.s099}},"acu-n6-l02":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Apunta un micrófono de condensador al traste 12, a unos 15–30 cm: es un buen punto de equilibrio. Si lo apuntas a la boca, tendrás más graves (y retumbe); hacia el puente, más brillo.","Con dos micrófonos puedes grabar en estéreo: uno al traste 12 y otro cerca del puente o del cuerpo."],tips:["Graba unos segundos, escucha con audífonos y mueve el micrófono antes de grabar la toma."]},practica:{paragraphs:["Prepara: afina, cambia cuerdas si suenan opacas, elige un cuarto silencioso. Coloca el micrófono, ajusta la ganancia para que el pico máximo quede alrededor de −10 dB y graba."],tips:["Evita moverte mucho al tocar: cambia la distancia y el sonido."]},lectura:a.s100,oido:a.s101}},"acu-n6-l03":{status:"borrador",generated:!0,sections:{teoria:a.s102,practica:a.s103,lectura:a.s104,oido:a.s105}},"acu-n6-l04":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["Doblar una guitarra es grabarla dos veces y panear cada toma a un lado: suena amplia. También puedes grabar una segunda guitarra con capo en otra posición o con arpegio en vez de rasgueo. Las voces dobles en el coro dan fuerza."],tips:["Cada capa debe aportar algo distinto: no repitas lo mismo en el mismo registro."]},practica:{paragraphs:["Graba el rasgueo en una pista y un arpegio (o la misma progresión con capo) en otra. Panea el rasgueo a un lado y el arpegio al otro."],tips:["Graba con metrónomo para que ambas pistas coincidan."]},lectura:a.s106,oido:a.s107}},"acu-n6-l05":{status:"borrador",generated:!0,sections:{teoria:a.s108,practica:a.s109,lectura:a.s110,oido:a.s111}},"acu-n6-l06":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["El cantautor compone y canta sus canciones acompañándose de la guitarra. La guitarra sostiene la voz, marca el ritmo y la emoción, sin taparla. Referentes: Silvio Rodríguez, Joaquín Sabina, Joan Manuel Serrat, Natalia Lafourcade, Ed Sheeran."],tips:["Elige un acompañamiento sencillo para que la letra sea la protagonista."]},practica:{paragraphs:["Toca y canta una canción completa con dinámica: verso más suave (arpegio), coro más fuerte (rasgueo). Ajusta el tono con el capo para que tu voz esté cómoda."],tips:["Grábate y revisa si la voz se entiende sobre la guitarra."]},lectura:{paragraphs:["Una hoja de cantautor combina letra, acordes encima de las sílabas y un patrón de rasgueo indicado al principio o en cada sección. Puede indicar capo y estructura."],tips:["Antes de tocar, lee toda la hoja e identifica las secciones."]},oido:{paragraphs:["Escucha una grabación de guitarra y voz y decide si la voz se entiende claramente sobre la guitarra."],tips:["Si la guitarra tapa la voz, toca más suave o baja su volumen en la mezcla."]}}},"acu-n6-l07":{status:"borrador",generated:!0,sections:{teoria:a.s112,practica:a.s113,lectura:a.s114,oido:a.s115}},"acu-n6-l08":{status:"borrador",generated:!0,sections:{teoria:a.s116,practica:{paragraphs:["Graba las guitarras de tu proyecto final. Afina antes de cada toma, cuida la posición del micrófono y elige las mejores tomas por sección."],tips:["Anota la posición del micrófono para que todas las sesiones suenen igual."]},lectura:a.s117,oido:{paragraphs:["En la mezcla final, la voz debe estar al frente y la guitarra sosteniéndola. Escucha y decide si el balance es correcto."],tips:["Prueba la mezcla en audífonos y en la bocina del celular."]}}},"acu-n6-l09":{status:"borrador",generated:!0,sections:{teoria:a.s118,practica:a.s119,lectura:a.s120,oido:a.s121}},"acu-n6-l10":{status:"borrador",generated:!0,sections:{teoria:a.s122,practica:a.s123,lectura:a.s124,oido:a.s125}},"acu-n6-l11":{status:"borrador",generated:!0,sections:{teoria:{paragraphs:["En vivo, la acústica se amplifica con pastilla (práctica, sin acoples) o con micrófono (sonido más natural). Muchas electroacústicas traen preamplificador con ecualizador y afinador. Pide en el monitor tu guitarra y tu voz."],tips:["Lleva una pila de repuesto para el preamplificador y un cable extra."]},practica:a.s126,lectura:a.s127,oido:a.s128}},"acu-n6-l12":{status:"borrador",generated:!0,sections:{teoria:a.s129,practica:{paragraphs:["Repasa las técnicas principales del curso en la guitarra acústica, del nivel 1 al 6, con metrónomo. Detecta las que ya dominas y las que necesitas seguir practicando.","Organiza una rutina de mantenimiento para después del curso: técnica, repertorio y creación."],tips:["Grábate tocando una pieza de cada nivel: verás todo lo que has avanzado."]},lectura:a.s130,oido:a.s131}}},s={...e};export{s as CONTENT};
